A(('h1', 'CHƯƠNG 4. ĐÁNH ĐỔI VÀ RỦI RO CỦA KIẾN TRÚC'))
A(('h2', '4.1. Các quyết định chính và đánh đổi'))
A(('p', 'Mỗi quyết định ở Chương 3 đều đánh đổi giữa độc lập, độ tin cậy và chi phí vận hành. Bảng 4.1 ghi lại các quyết định lớn, lý do chọn và cái giá nhóm chấp nhận.'))
A(('table', 'Bảng 4.1. Quyết định kiến trúc và đánh đổi', ['Quyết định', 'Lý do', 'Đánh đổi chấp nhận'], [['Tách bốn service thay vì giữ kiến trúc monolith', 'Mỗi service có ranh giới dữ liệu, đặc thù tải và kiểu lỗi riêng. Đáp ứng yêu cầu đề bài', 'Phát sinh độ trễ gọi qua mạng, thêm điểm có nguy cơ lỗi cục bộ và gỡ lỗi phức tạp hơn một process'], ['Dừng ở bốn service thay vì tách thành bảy service', 'Giữ số lượng container, database và call mạng ở mức nhóm ba người kiểm soát tốt', 'Phạm vi mỗi service lớn hơn, chẳng hạn core đảm nhận cả quản lý hộ gia đình lẫn tính hóa đơn'], ['Quy định chiều gọi đồng bộ một chiều', 'Không có circular dependency. Sự cố ở một service chỉ ảnh hưởng tầng ngay phía trên', 'Copilot phải đi vòng qua insight để lấy dữ liệu tiêu thụ, thêm một chặng gọi mạng so với đọc trực tiếp'], ['Truyền sự kiện qua RabbitMQ cho hai luồng phụ', 'Bên gửi không phải chờ bên nhận xử lý xong. Có sẵn DLQ để lưu giữ message lỗi và chạy lại', 'Read model của insight có độ trễ ngắn so với core (eventual consistency). Phải duy trì thêm bảng outbox và inbox'], ['Dùng một PostgreSQL server cho năm database', 'Giữ tổng số container ở mức tám trong khi vẫn tách biệt quyền theo từng database role', 'PostgreSQL server là điểm lỗi chung (single point of failure) về hạ tầng, các service chia sẻ tài nguyên trên cùng server'], ['Bốn service cùng ngôn ngữ Python và chung thư viện', 'Viết phần fault tolerance, log, outbox và inbox một lần. Giảm số công nghệ phải học', 'Backend gắn chặt với hệ sinh thái Python. Cập nhật thư viện chung ảnh hưởng tới cả bốn service'], ['Mỗi service chạy trong một container (API, consumer, relay chung process)', 'Dễ khởi chạy và gom toàn bộ log của một service về một luồng duy nhất', 'Không scale riêng được phần API và phần background job. Các job nền nặng cạnh tranh tài nguyên với API'], ['Tự viết circuit breaker và bulkhead trong thư viện chung', 'Thư viện sẵn có không tương thích gọn với mô hình async của FastAPI', 'Phải tự viết bộ kiểm thử kỹ lưỡng và thiếu các tính năng giám sát nâng cao của những thư viện phổ biến']], [2500, 3200, 3371]))
A(('h2', '4.2. Rủi ro còn lại và hướng xử lý'))
A(('p', 'Bảng 4.2 liệt kê các rủi ro đã nhận diện ở mức kiến trúc và cách xử lý. Cấu hình chi tiết và số liệu thực nghiệm sẽ nằm ở các chương về độ tin cậy và đánh giá.'))
A(('table', 'Bảng 4.2. Rủi ro và hướng xử lý', ['Rủi ro', 'Biểu hiện', 'Hướng xử lý'], [['Service nilm quá tải hoặc ngừng phản hồi', 'core không nhận được kết quả chạy inference ngay khi lưu batch', 'Giữ nguyên dữ liệu sensor gốc, đánh dấu batch `PENDING_INFERENCE` và dùng background job retry có backoff. Kết hợp circuit breaker ở core và bulkhead ở nilm'], ['Nhà cung cấp LLM phản hồi chậm hoặc lỗi', 'Copilot không trả lời kịp. Không được kéo theo nghẽn dashboard', 'Áp timeout 20 giây, mở circuit breaker và trả mã lỗi 503 rõ ràng. Dashboard và phân tích không phụ thuộc vào LLM'], ['Message đến lặp lại hoặc xử lý thất bại', 'Read model của insight bị cộng trùng hoặc thiếu dữ liệu mới', 'Dùng bảng inbox chống xử lý trùng, bảng outbox chống mất sự kiện và đẩy message lỗi vào DLQ để kiểm tra, chạy lại'], ['Read model của insight lệch so với core', 'Số liệu trên biểu đồ phân tích khác với số liệu hóa đơn', 'Quy định số liệu hóa đơn chính thức luôn lấy trực tiếp từ core. Cơ chế đồng bộ lại read model khi lệch sẽ được xác định ở phần triển khai'], ['Copilot trả lời sai số liệu thực tế', 'Người dùng nhận phải con số tiền điện hoặc công suất sai', 'Mọi con số đều do tool tính toán từ dữ liệu hộ gia đình. Module Verifier loại bỏ câu trả lời sai số liệu, đơn vị hoặc nguồn (BR8)'], ['Lộ thông tin cá nhân qua LLM hoặc Text-to-SQL', 'Prompt gửi đi chứa PII hoặc câu SQL tự sinh chạm dữ liệu nguồn', 'Module Guardrail ẩn PII trước khi gọi LLM. Truy vấn SQL chạy qua endpoint của insight với SQL guard trên database phân tích riêng'], ['Container PostgreSQL ngừng hoạt động', 'Mọi service mất kết nối dữ liệu cùng lúc', 'Chấp nhận trong phạm vi bài tập lớn. Hướng nâng cấp thực tế là tách database sang server riêng hoặc cấu hình replica dự phòng']], [2300, 2700, 4071]))
